from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error
from taf.sbts.oam.coam.admin.utils.validators import ObjectValidator, AnyObjectValidator, AllObjectsValidator, NoneObjectsValidator


class CommonInterface21B(object):
    def get_managed_objects(self, class_name, timeout):
        """
        Retrieves infomodel object with its parameters.

        :param class_name: eg. 'SMOD', 'RMOD'... Possibly every infomodel object class name.
        :param int timeout: Timeout for the operation.
        :return list: list with managed objects and their parameters.

        More details (content of requestMessage is returned data):
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getItemsByClassName.html
        """
        managed_objects = self._api_client.execute_infomodel_request(
            name='getItemsByClassName',
            parameters={'className': class_name},
            timeout=timeout)
        return managed_objects

    def get_parameters(self, dist_name, pattern=".*", depth=-1, timeout=60):
        """
        Get managed object parameters from Node-B InfoModel. If no 'pattern' specified,
        function returns all parameters of managed object.

        :param str dist_name: Object dist name.
        :param str pattern: Parameters name pattern (regex). Defaults to regex ".*".
        :param int depth: One of [0 | -1], 0 gets complex value of parameter.
        :param int timeout: Timeout for the operation.
        :raises DataNotAvailable: If parameter has not been provided for this distName by M-Plane.
        :return dict: Object’s parameters dict filtered by pattern.

        Example

        ::

            {
            u'clusterId': None,
            u'productCode': u'474021A.M01',
            u'requestedResetType': None,
            u'serialNumber': u'L1182214824',
            u'stateInfo': {u'administrativeState': u'Unlocked',
                            u'availabilityStatus': None,
                            u'operationalState': u'Enabled',
                            u'usageState': u'Idle'},
             u'syncMode': u'Frequency',
             u'variant': u'ASIK'
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getParameters.html
        """
        parameters = {'distName': dist_name, 'pattern': pattern, 'depth': depth}
        result = self._api_client.execute_infomodel_request('getParameters', parameters, timeout)

        if result is None:
            raise DataNotAvailable("Parameter has not been provided for this distName by M-Plane.")
        return result

    def check_if_(self, class_name, id, parameters=None, timeout=10):
        """
        Assert that item exists and matches given parameters.

        :param string class_name: "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                                  "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string id: item ID
        :param string parameters: Required item parameters. None means no parameter value validation.
        :param int timeout: Time to wait for matching item.

        :return dict: dict with class name info

        More info at https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-subscribeForParameters.html

        |

        **PARAMETERS syntax:**
            - PARAMETER1 OPERATOR1 VALUE1, PARAMETER2 OPERATOR2 VALUE2, ...
                * example: status=disabled, temperature>100, temperature<=120
                * single spaces between elements are allowed with one exception - see empty VALUE
            - PARAMETERs:
                * simple: temperature, status, etc.
                * nested: stateInfo.availabilityStatus, etc.
                * lists: alarms[5], stateInfo.reasoningStatus[?], alarms[*]
                    * \\* means all elements
                    * ? means any element
            - OPERATORs: >, <, >=, <=, =, !=
            - VALUEs:
                * literal: 5, disabled
                * regex:
                    * positive match: parameter=regex"[Oo]nline"
                    * negative match: parameter!=regex"validated|onAirDone"
                * empty: string 'empty' is interpreted as an empty value, but there may be no space before it
                    * correct: parameter=empty, parameter !=empty
                    * incorrect: parameter = empty

        |

        """  # noqa: W605
        class_name = class_name.upper()
        if class_name not in ("RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                              "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                              "CABINET", "CARRIERGROUPC", "FHS"):
            raise_value_error(param="class_name",
                              value=str(class_name),
                              subpage="tutorial-subscribeForParameters.html")
        return self._api_client.execute_infomodel_subscription(
            "subscribeForParameters", {"className": class_name, "id": id}, ObjectValidator(parameters), timeout)

    def check_if_any(self, class_name, parameters=None, timeout=10, **kwargs):
        """
        Assert that any item of given class exists and matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching item.

        :return dict: dict with class name info

        """
        return self._subscribe_all_parameters(class_name, AnyObjectValidator, parameters, timeout)

    def check_if_every(self, class_name, parameters, timeout=10, **kwargs):
        """
        Assert that every item of given class matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.

        :return dict: dict with class name info

        """
        return self._subscribe_all_parameters(class_name, AllObjectsValidator, parameters, timeout)

    def check_if_no(self, class_name, parameters=None, timeout=10, **kwargs):
        """
        Assert that no item of given class exists or matches given parameters.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.

        :return dict: dict with class name info
        """
        return self._subscribe_all_parameters(class_name, NoneObjectsValidator, parameters, timeout)

    def _subscribe_all_parameters(self, class_name, validator, parameters=None, timeout=10, **kwargs):
        """
        Perform subscription for subscribeForAllParameters CLI request and perform validation.

        :param string class_name: One of "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL",
                                  "BBMOD", "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS".
        :param validator ObjectValidator: Validtor see taf.sbts.oam.coam.admin.utils.validators
        :param string parameters: Requierd item parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param int timeout: Time to wait for matching items.

        More info at https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-subscribeForAllParameters.html
        """
        class_name = class_name.upper()
        if class_name not in ("RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                              "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                              "CABINET", "CARRIERGROUPC", "FHS"):
            raise_value_error(param="class_name",
                              value=str(class_name),
                              subpage="tutorial-subscribeForAllParameters.html")

        return self._api_client.execute_infomodel_subscription(
            "subscribeForAllParameters", {"className": class_name}, validator(parameters), timeout)
